{"command":"cat > src/settings.rs <<'RS'
use regex::Regex;
use serde::Deserialize;
use std::error::Error;
use std::ffi::OsStr;
use std::fs;
use std::path::PathBuf;

pub type BoxError = Box<dyn Error>;

pub const PRESET_MODELS: [(&str, &str); 3] = [
    ("git-flow", include_str!("models/git-flow.toml")),
    ("simple", include_str!("models/simple.toml")),
    ("none", include_str!("models/none.toml")),
];

pub fn get_models_dir() -> Result<PathBuf, BoxError> {
    let config_dir = dirs::config_dir()
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::NotFound, "could not determine config directory"))?;
    let dir = config_dir.join("git-graph").join("models");
    if !dir.exists() {
        fs::create_dir_all(&dir)?;
        for (name, content) in PRESET_MODELS {
            fs::write(dir.join(format!("{name}.toml")), content)?;
        }
    }
    Ok(dir)
}

pub fn available_models(models_dir: &PathBuf) -> Result<Vec<String>, BoxError> {
    let mut models = Vec::new();
    for entry in fs::read_dir(models_dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension() == Some(OsStr::new("toml")) {
            if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                models.push(stem.to_owned());
            }
        }
    }
    Ok(models)
}

pub fn no_model_error(model: &str, models_dir: &PathBuf) -> BoxError {
    // The caller formats the available list when it can; this helper is kept for
    // symmetry with the original flows that need the plain message.
    format!(
        "ERROR: No branching model named '{}' found in {}",
        model,
        models_dir.display()
    )
    .into()
}

#[derive(Debug, Deserialize)]
pub struct RepoSettings {
    pub model: String,
}

#[derive(Debug, Deserialize)]
struct RawColorSettings {
    matches: Vec<(String, Vec<String>)>,
    unknown: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct RawBranchSettings {
    persistence: Vec<String>,
    order: Vec<String>,
    terminal_colors: RawColorSettings,
    svg_colors: RawColorSettings,
}

#[derive(Debug, Clone)]
pub struct CompiledColors {
    pub matches: Vec<(Regex, Vec<String>)>,
    pub unknown: Vec<String>,
}

#[derive(Debug, Clone)]
pub struct BranchSettings {
    pub persistence: Vec<Regex>,
    pub order: Vec<Regex>,
    pub terminal_colors: CompiledColors,
    pub svg_colors: CompiledColors,
}

fn compile_regexes(patterns: &[String]) -> Result<Vec<Regex>, BoxError> {
    let mut out = Vec::with_capacity(patterns.len());
    for p in patterns {
        out.push(Regex::new(p)?);
    }
    Ok(out)
}

fn compile_colors(raw: RawColorSettings) -> Result<CompiledColors, BoxError> {
    let mut matches = Vec::with_capacity(raw.matches.len());
    for (pat, colors) in raw.matches {
        matches.push((Regex::new(&pat)?, colors));
    }
    Ok(CompiledColors {
        matches,
        unknown: raw.unknown,
    })
}

pub fn load_branch_settings(models_dir: &PathBuf, model: &str) -> Result<BranchSettings, BoxError> {
    let path = models_dir.join(format!("{model}.toml"));
    if !path.exists() {
        let models = available_models(models_dir)?;
        return Err(format!(
            "ERROR: No branching model named '{}' found in {}\n       Available models are: {}",
            model,
            models_dir.display(),
            models.join(", ")
        )
        .into());
    }
    let content = fs::read_to_string(&path)?;
    let raw: RawBranchSettings = toml::from_str(&content)?;
    let persistence = compile_regexes(&raw.persistence)?;
    let order = compile_regexes(&raw.order)?;
    let terminal_colors = compile_colors(raw.terminal_colors)?;
    let svg_colors = compile_colors(raw.svg_colors)?;
    Ok(BranchSettings {
        persistence,
        order,
        terminal_colors,
        svg_colors,
    })
}

pub fn stripped_name<'a>(name: &'a str) -> &'a str {
    name.strip_prefix("origin/").unwrap_or(name)
}

impl BranchSettings {
    pub fn persistence(&self, name: &str) -> usize {
        let n = stripped_name(name);
        for (i, re) in self.persistence.iter().enumerate() {
            if re.is_match(n) {
                return i;
            }
        }
        self.persistence.len()
    }

    pub fn order_group(&self, name: &str) -> usize {
        let n = stripped_name(name);
        for (i, re) in self.order.iter().enumerate() {
            if re.is_match(n) {
                return i;
            }
        }
        self.order.len()
    }

    fn choose_color<'a>(&self, settings: &'a CompiledColors, name: &str, index: usize) -> &'a str {
        let n = stripped_name(name);
        for (re, colors) in &settings.matches {
            if re.is_match(n) {
                return &colors[index % colors.len()];
            }
        }
        &settings.unknown[index % settings.unknown.len()]
    }

    pub fn terminal_color(&self, name: &str, index: usize) -> Result<u8, BoxError> {
        let s = self.choose_color(&self.terminal_colors, name, index);
        parse_terminal_color(s)
    }

    pub fn svg_color(&self, name: &str, index: usize) -> String {
        self.choose_color(&self.svg_colors, name, index).to_owned()
    }
}

pub fn parse_terminal_color(s: &str) -> Result<u8, BoxError> {
    let v = match s {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" => 5,
        "cyan" => 6,
        "white" => 7,
        "bright_black" => 8,
        "bright_red" => 9,
        "bright_green" => 10,
        "bright_yellow" => 11,
        "bright_blue" => 12,
        "bright_magenta" => 13,
        "bright_cyan" => 14,
        "bright_white" => 15,
        _ => {
            if let Ok(n) = s.parse::<u8>() {
                n
            } else {
                return Err(format!("Color {s} not found").into());
            }
        }
    };
    Ok(v)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Style {
    Thin,
    Round,
    Bold,
    Double,
    Ascii,
}

pub fn parse_style(s: &str) -> Result<Style, BoxError> {
    match s {
        "normal" | "thin" | "n" | "t" => Ok(Style::Thin),
        "round" | "r" => Ok(Style::Round),
        "bold" | "b" => Ok(Style::Bold),
        "double" | "d" => Ok(Style::Double),
        "ascii" | "a" => Ok(Style::Ascii),
        _ => Err(format!(
            "Unknown characters/style '{s}'. Must be one of [normal|thin|round|bold|double|ascii]"
        )
        .into()),
    }
}

pub const UP: u8 = 1;
pub const DOWN: u8 = 2;
pub const LEFT: u8 = 4;
pub const RIGHT: u8 = 8;

impl Style {
    pub fn glyph(&self, mask: u8) -> char {
        match self {
            Style::Thin => thin_glyph(mask, false),
            Style::Round => thin_glyph(mask, true),
            Style::Bold => match mask {
                0 => ' ',
                m if m == UP || m == DOWN || m == UP | DOWN => '┃',
                m if m == LEFT || m == RIGHT || m == LEFT | RIGHT => '━',
                m if m == DOWN | RIGHT => '┏',
                m if m == DOWN | LEFT => '┓',
                m if m == UP | RIGHT => '┗',
                m if m == UP | LEFT => '┛',
                m if m == UP | DOWN | RIGHT => '┣',
                m if m == UP | DOWN | LEFT => '┫',
                m if m == DOWN | LEFT | RIGHT => '┳',
                m if m == UP | LEFT | RIGHT => '┻',
                _ => '╋',
            },
            Style::Double => match mask {
                0 => ' ',
                m if m == UP || m == DOWN || m == UP | DOWN => '║',
                m if m == LEFT || m == RIGHT || m == LEFT | RIGHT => '═',
                m if m == DOWN | RIGHT => '╔',
                m if m == DOWN | LEFT => '╗',
                m if m == UP | RIGHT => '╚',
                m if m == UP | LEFT => '╝',
                m if m == UP | DOWN | RIGHT => '╠',
                m if m == UP | DOWN | LEFT => '╣',
                m if m == DOWN | LEFT | RIGHT => '╦',
                m if m == UP | LEFT | RIGHT => '╩',
                _ => '╬',
            },
            Style::Ascii => match mask {
                0 => ' ',
                m if m == DOWN | RIGHT || m == DOWN | LEFT => '.',
                m if m == UP | RIGHT || m == UP | LEFT => '\'',
                m if m == DOWN | LEFT | RIGHT || m == UP | LEFT | RIGHT || m == UP | DOWN | LEFT | RIGHT => '+',
                m if m & (LEFT | RIGHT) != 0 && m & (UP | DOWN) == 0 => '-',
                m if m & (UP | DOWN) != 0 && m & (LEFT | RIGHT) == 0 => '|',
                // tees with a vertical line through them render as | in ascii
                m if m == UP | DOWN | RIGHT || m == UP | DOWN | LEFT => '|',
                _ => '+',
            },
        }
    }

    pub fn dot(&self, is_merge: bool) -> char {
        match self {
            Style::Ascii => {
                if is_merge {
                    'o'
                } else {
                    '*'
                }
            }
            _ => {
                if is_merge {
                    '○'
                } else {
                    '●'
                }
            }
        }
    }

    pub fn horizontal(&self) -> char {
        self.glyph(LEFT | RIGHT)
    }
}

fn thin_glyph(mask: u8, round: bool) -> char {
    match mask {
        0 => ' ',
        m if m == UP || m == DOWN || m == UP | DOWN => '│',
        m if m == LEFT || m == RIGHT || m == LEFT | RIGHT => '─',
        m if m == DOWN | RIGHT => {
            if round {
                '╭'
            } else {
                '┌'
            }
        }
        m if m == DOWN | LEFT => {
            if round {
                '╮'
            } else {
                '┐'
            }
        }
        m if m == UP | RIGHT => {
            if round {
                '╰'
            } else {
                '└'
            }
        }
        m if m == UP | LEFT => {
            if round {
                '╯'
            } else {
                '┘'
            }
        }
        m if m == UP | DOWN | RIGHT => '├',
        m if m == UP | DOWN | LEFT => '┤',
        m if m == DOWN | LEFT | RIGHT => '┬',
        m if m == UP | LEFT | RIGHT => '┴',
        _ => '┼',
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorMode {
    Auto,
    Always,
    Never,
}

pub fn parse_color_mode(s: &str) -> Result<ColorMode, BoxError> {
    match s {
        "auto" => Ok(ColorMode::Auto),
        "always" => Ok(ColorMode::Always),
        "never" => Ok(ColorMode::Never),
        _ => Err(format!("Unknown color mode '{s}'. Supports [auto|always|never].").into()),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WrapWidth {
    Auto,
    None,
    Fixed(usize),
}

#[derive(Debug, Clone, Copy)]
pub struct WrapSettings {
    pub width: WrapWidth,
    pub indent1: usize,
    pub indent2: usize,
}

impl Default for WrapSettings {
    fn default() -> Self {
        Self {
            width: WrapWidth::Auto,
            indent1: 0,
            indent2: 8,
        }
    }
}

pub fn parse_wrap(values: Option<Vec<&String>>) -> Result<WrapSettings, BoxError> {
    let Some(values) = values else {
        return Ok(WrapSettings::default());
    };
    if values.is_empty() {
        return Ok(WrapSettings::default());
    }
    let joined = values
        .iter()
        .map(|s| s.as_str())
        .collect::<Vec<_>>()
        .join(" ");
    let err = || -> BoxError {
        format!("ERROR: Can't parse option --wrap '{joined}' to integers.").into()
    };
    let width = match values[0].as_str() {
        "auto" => WrapWidth::Auto,
        "none" => WrapWidth::None,
        v => {
            if let Ok(n) = v.parse::<usize>() {
                WrapWidth::Fixed(n)
            } else {
                return Err(err());
            }
        }
    };
    let mut indent1 = 0usize;
    let mut indent2 = 0usize;
    if values.len() > 1 {
        indent1 = values[1].parse::<usize>().map_err(|_| err())?;
    }
    if values.len() > 2 {
        indent2 = values[2].parse::<usize>().map_err(|_| err())?;
    }
    Ok(WrapSettings {
        width,
        indent1,
        indent2,
    })
}
