impl GitGraph {
    pub fn new(
        repo: &Repository,
        settings: &BranchSettings,
        local_only: bool,
        max_count: Option<usize>,
    ) -> Result<GitGraph, BoxError> {
        // HEAD is resolved first: an unborn HEAD aborts here.
        let head_ref = repo.head()?;
        let head_branch = if head_ref.is_branch() {
            head_ref.shorthand().map(|s| s.to_owned())
        } else {
            None
        };
        let head_oid = match head_ref.target() {
            Some(oid) => Some(oid),
            None => head_ref.peel_to_commit().ok().map(|c| c.id()),
        };

        let mut counter: usize = 0;
        let mut branches: Vec<BranchInfo> = Vec::new();

        let branch_filter = if local_only {
            Some(BranchType::Local)
        } else {
            None
        };
        for item in repo.branches(branch_filter)? {
            let (branch, _ty) = item?;
            let name = match branch.name() {
                Ok(Some(n)) => n.to_owned(),
                _ => continue,
            };
            let Some(tip) = branch.get().target() else {
                continue;
            };
            branches.push(make_branch(
                name,
                tip,
                BranchKind::Real,
                None,
                settings,
                &mut counter,
            )?);
        }

        // Tags, named internally tags/<name>.
        for item in repo.references_glob("refs/tags/*")? {
            let reference = item?;
            let full = reference.name_bytes();
            let short = full.strip_prefix(b"refs/").unwrap_or(full);
            let name = String::from_utf8(short.to_vec())?;
            let Ok(commit) = reference.peel_to_commit() else {
                continue;
            };
            branches.push(make_branch(
                name,
                commit.id(),
                BranchKind::Tag,
                None,
                settings,
                &mut counter,
            )?);
        }

        // Commit list, newest first.
        let mut walk = repo.revwalk()?;
        walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;
        for b in &branches {
            let _ = walk.push(b.tip);
        }
        let limit = max_count.unwrap_or(usize::MAX);
        let mut raw_commits: Vec<CommitInfo> = Vec::new();
        for oid_res in walk.take(limit) {
            let oid = oid_res?;
            let commit = repo.find_commit(oid)?;
            raw_commits.push(CommitInfo::from_commit(&commit));
        }

        let raw_index: HashMap<Oid, usize> = raw_commits
            .iter()
            .enumerate()
            .map(|(i, c)| (c.oid, i))
            .collect();

        // Branches implied by merge commits (for deleted branches).
        let real_branch_snapshot: Vec<(String, Oid)> =
            branches.iter().map(|b| (b.name.clone(), b.tip)).collect();
        let mut merge_branches: Vec<BranchInfo> = Vec::new();
        for (mi, commit) in raw_commits.iter().enumerate() {
            if commit.parents.len() < 2 {
                continue;
            }
            let second = commit.parents[1];
            let name =
                parse_merge_branch_name(&commit.summary).unwrap_or_else(|| "unknown".to_owned());
            let mut info = make_branch(
                name.clone(),
                second,
                BranchKind::Merge,
                Some(commit.oid),
                settings,
                &mut counter,
            )?;
            // If an existing branch with exactly this name already starts
            // at the very next commit, the implied branch is redundant and
            // the existing branch takes over its commits.
            let tip_index = raw_index.get(&second).copied();
            if tip_index == Some(mi + 1)
                && real_branch_snapshot
                    .iter()
                    .any(|(n, t)| *n == name && *t == second)
            {
                info.skip_trace = true;
            }
            merge_branches.push(info);
        }
        branches.extend(merge_branches);

        // Sort candidates for tracing: by persistence, then implied merge
        // branches before real branches before tags. The sort is stable, so
        // candidates keep their discovery order within each of those
        // groups.
        fn kind_rank(k: BranchKind) -> usize {
            match k {
                BranchKind::Merge => 0,
                BranchKind::Real => 1,
                BranchKind::Tag => 2,
            }
        }
        // Dedup-skipped candidates are dropped before tracing, but they
        // already consumed a colour index above.
        branches.retain(|b| !b.skip_trace);
        branches.sort_by_key(|b| (b.persistence, kind_rank(b.kind)));

        // Trace each branch along first parents.
        for bi in 0..branches.len() {
            let mut oid = branches[bi].tip;
            loop {
                let Some(&ri) = raw_index.get(&oid) else {
                    break;
                };
                if raw_commits[ri].branch.is_some() {
                    break;
                }
                raw_commits[ri].branch = Some(bi);
                if raw_commits[ri].parents.is_empty() {
                    break;
                }
                oid = raw_commits[ri].parents[0];
            }
        }

        // Drop implied merge branches that did not claim any commit, and
        // remap branch indices of commits.
        let mut assigned_count = vec![0usize; branches.len()];
        for c in &raw_commits {
            if let Some(bi) = c.branch {
                assigned_count[bi] += 1;
            }
        }
        let mut remap: HashMap<usize, usize> = HashMap::new();
        let mut final_branches: Vec<BranchInfo> = Vec::new();
        for (old_idx, b) in branches.into_iter().enumerate() {
            if b.kind == BranchKind::Merge && assigned_count[old_idx] == 0 {
                continue;
            }
            remap.insert(old_idx, final_branches.len());
            final_branches.push(b);
        }

        // Filter out commits that were not assigned to any branch.
        let mut commits: Vec<CommitInfo> = Vec::new();
        for mut c in raw_commits {
            let Some(old) = c.branch else { continue };
            let Some(&new_idx) = remap.get(&old) else {
                continue;
            };
            c.branch = Some(new_idx);
            commits.push(c);
        }
        let oid_index: HashMap<Oid, usize> =
            commits.iter().enumerate().map(|(i, c)| (c.oid, i)).collect();
        let n = commits.len();

        // Branch ranges and source/target groups.
        for bi in 0..final_branches.len() {
            let assigned: Vec<usize> = commits
                .iter()
                .enumerate()
                .filter(|(_, c)| c.branch == Some(bi))
                .map(|(i, _)| i)
                .collect();
            if assigned.is_empty() {
                continue;
            }
            let first = *assigned.iter().min().unwrap();
            let last = *assigned.iter().max().unwrap();
            let start = if final_branches[bi].kind == BranchKind::Merge {
                match final_branches[bi]
                    .target_merge
                    .and_then(|oid| oid_index.get(&oid).copied())
                {
                    Some(mi) => mi + 1,
                    None => first,
                }
            } else {
                first
            };
            let oldest = &commits[last];
            let (end, mut source_group): (Option<usize>, Option<usize>) =
                if oldest.parents.is_empty() {
                    (Some(last), None)
                } else if let Some(&pi) = oid_index.get(&oldest.parents[0]) {
                    let sg = commits[pi]
                        .branch
                        .map(|pb| final_branches[pb].order_group);
                    (Some(pi - 1), sg)
                } else {
                    (None, None)
                };
            if source_group.is_none() {
                // Fall back to the oldest merge into this branch.
                for &idx in assigned.iter().rev() {
                    let c = &commits[idx];
                    if c.parents.len() >= 2 {
                        if let Some(&si) = oid_index.get(&c.parents[1]) {
                            source_group = commits[si]
                                .branch
                                .map(|pb| final_branches[pb].order_group);
                            break;
                        }
                    }
                }
            }
            let target_group = if final_branches[bi].kind == BranchKind::Merge {
                final_branches[bi]
                    .target_merge
                    .and_then(|oid| oid_index.get(&oid).copied())
                    .and_then(|mi| commits[mi].branch)
                    .map(|tb| final_branches[tb].order_group)
            } else {
                None
            };
            final_branches[bi].range = (Some(start), end);
            final_branches[bi].source_group = source_group;
            final_branches[bi].target_group = target_group;
        }

        // Column assignment, per order group.
        let num_groups = settings.order.len() + 1;
        let mut branches_sort: Vec<usize> = final_branches
            .iter()
            .enumerate()
            .filter(|(_, b)| b.range.0.is_some())
            .map(|(i, _)| i)
            .collect();
        branches_sort.sort_by_key(|&bi| {
            let b = &final_branches[bi];
            let start = b.range.0.unwrap_or(0);
            let end = b.range.1.unwrap_or(n);
            (end - start, start)
        });
        let mut occupied: Vec<Vec<Vec<(usize, usize)>>> = vec![Vec::new(); num_groups];
        let mut within_group: HashMap<usize, usize> = HashMap::new();
        for &bi in &branches_sort {
            let (start, end, group) = {
                let b = &final_branches[bi];
                (
                    b.range.0.unwrap_or(0),
                    b.range.1.unwrap_or(n),
                    b.order_group.min(num_groups - 1),
                )
            };
            let slots = &mut occupied[group];
            let mut chosen: Option<usize> = None;
            for (si, slot) in slots.iter().enumerate() {
                let overlaps = slot
                    .iter()
                    .any(|&(s2, e2)| start <= e2 && s2 <= end);
                if !overlaps {
                    chosen = Some(si);
                    break;
                }
            }
            let si = match chosen {
                Some(si) => si,
                None => {
                    slots.push(Vec::new());
                    slots.len() - 1
                }
            };
            slots[si].push((start, end));
            within_group.insert(bi, si);
        }
        let mut group_offsets: Vec<usize> = Vec::with_capacity(num_groups);
        let mut acc = 0usize;
        for g in 0..num_groups {
            group_offsets.push(acc);
            acc += occupied[g].len();
        }
        let num_columns = acc;
        for (bi, si) in within_group {
            let g = final_branches[bi].order_group.min(num_groups - 1);
            final_branches[bi].column = group_offsets[g] + si;
        }

        // Refs (branches and tags) shown on their tip commits.
        for bi in 0..final_branches.len() {
            let b = &final_branches[bi];
            if b.kind == BranchKind::Merge {
                continue;
            }
            let Some(&ci) = oid_index.get(&b.tip) else {
                continue;
            };
            if b.kind == BranchKind::Tag {
                let display = b
                    .name
                    .strip_prefix("tags/")
                    .unwrap_or(&b.name)
                    .to_owned();
                commits[ci].tag_refs.push(display);
            } else {
                commits[ci]
                    .branch_refs
                    .push((b.name.clone(), b.terminal_color));
            }
        }

        Ok(GitGraph {
            commits,
            branches: final_branches,
            head_oid,
            head_branch,
            oid_index,
            num_columns,
        })
    }

    pub fn branch_column_of_commit(&self, idx: usize) -> usize {
        self.commits[idx]
            .branch
            .map(|b| self.branches[b].column)
            .unwrap_or(99)
    }
}
