                let Some(&ri) = raw_index.get(&oid) else {
                    break;
                };
                if raw_commits[ri].branch.is_some() {
                    break;
                }
                raw_commits[ri].branch = Some(bi);
                if raw_commits[ri].parents.is_empty() {
