        }

        // Drop implied merge branches that did not claim any commit, and
        // remap branch indices of commits.
        let mut assigned_count = vec![0usize; branches.len()];
        for c in &raw_commits {
            if let Some(bi) = c.branch {
                assigned_count[bi] += 1;
            }
        }
        let mut remap: HashMap<usize, usize> = HashMap::new();
        let mut final_branches: Vec<BranchInfo> = Vec::new();
        for (old_idx, b) in branches.into_iter().enumerate() {
            if b.kind == BranchKind::Merge && assigned_count[old_idx] == 0 {
