            commits,
            branches: final_branches,
            head_oid,
            head_branch,
            oid_index,
            num_columns,
        })
    }

    pub fn branch_column_of_commit(&self, idx: usize) -> usize {
        self.commits[idx]
            .branch
            .map(|b| self.branches[b].column)
            .unwrap_or(99)
    }
