pub fn parse_merge_branch_name(summary: &str) -> Option<String> {
    // Three message shapes are recognised, matching the summaries produced
    // by git's own merges, by GitHub-style pull-request merges, and by
    // Bitbucket-style "Merged in ..." merges.
    // 1. Merge branch '<name>' [of ...|into ...]
    // The capture is non-greedy, but may extend to a later quote if the
    // text after the first closing quote is not a recognised suffix.
    if let Ok(re) = Regex::new(r"^Merge branch '(.+?)'(?: of .+| into .+)?$") {
        if let Some(c) = re.captures(summary) {
            let name = c.get(1).unwrap().as_str();
            if !name.is_empty() {
                return Some(name.to_owned());
            }
        }
    }
    // 2. Merge pull request #<n> from <user>/<name>
    // The user part must be at least two characters long.
    if let Ok(re) = Regex::new(r"^Merge pull request #[0-9]+ from [^/]{2,}/(.+)$") {
        if let Some(c) = re.captures(summary) {
            let name = c.get(1).unwrap().as_str();
            if !name.is_empty() {
                return Some(name.to_owned());
            }
        }
    }
    // 3. Merged in <name> (pull request #<n>)
    if let Ok(re) = Regex::new(r"^Merged in (.+) \(pull request #[0-9]+\)$") {
        if let Some(c) = re.captures(summary) {
            let name = c.get(1).unwrap().as_str();
            if !name.is_empty() {
                return Some(name.to_owned());
            }
        }
    }
    None
}

