use crate::graph::{CommitInfo, GitGraph};
use crate::settings::{WrapSettings, WrapWidth};
use chrono::{DateTime, FixedOffset, TimeZone, Utc};
use git2::{Oid, Time};
use unicode_width::UnicodeWidthChar;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StyledChar {
    pub ch: char,
    pub color: Option<u8>,
    pub span: u32,
}

pub type StyledLine = Vec<StyledChar>;

fn plain(s: &str) -> StyledLine {
    s.chars()
        .map(|ch| StyledChar {
            ch,
            color: None,
            span: 0,
        })
        .collect()
}

fn colored(s: &str, color: u8, span: u32) -> StyledLine {
    s.chars()
        .map(|ch| StyledChar {
            ch,
            color: Some(color),
            span,
        })
        .collect()
}

fn next_span(counter: &mut u32) -> u32 {
    *counter += 1;
    *counter
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CommitFormat {
    Oneline,
    Short,
    Medium,
    Full,
    Custom(String),
}

pub fn parse_format(value: Option<&String>) -> CommitFormat {
    match value.map(|s| s.as_str()) {
        None => CommitFormat::Oneline,
        Some("oneline") | Some("o") => CommitFormat::Oneline,
        Some("short") | Some("s") => CommitFormat::Short,
        Some("medium") | Some("m") => CommitFormat::Medium,
        Some("full") | Some("f") => CommitFormat::Full,
        Some(other) => CommitFormat::Custom(other.to_owned()),
    }
}

pub fn abbrev(oid: Oid) -> String {
    let s = oid.to_string();
    s[..7].to_owned()
}

fn datetime_of(time: Time) -> DateTime<FixedOffset> {
    let offset_secs = (time.offset_minutes() * 60) as i32;
    let offset = FixedOffset::east_opt(offset_secs).unwrap_or_else(|| FixedOffset::east_opt(0).unwrap());
    let utc = DateTime::<Utc>::from_timestamp(time.seconds(), 0)
        .unwrap_or_else(|| DateTime::<Utc>::from_timestamp(0, 0).unwrap());
    utc.with_timezone(&offset)
}

pub fn format_date(time: Time) -> String {
    datetime_of(time).format("%a %b %e %H:%M:%S %Y %z").to_string()
}

pub fn format_date_short(time: Time) -> String {
    datetime_of(time).format("%Y-%m-%d").to_string()
}

pub fn format_date_relative(time: Time) -> String {
    let now = Utc::now().timestamp();
    let diff = now - time.seconds();
    const MIN: i64 = 60;
    const HOUR: i64 = 60 * MIN;
    const DAY: i64 = 24 * HOUR;
    if diff < MIN {
        format!("{diff} seconds ago")
    } else if diff < HOUR {
        format!("{} minutes ago", diff / MIN)
    } else if diff < DAY {
        format!("{} hours ago", diff / HOUR)
    } else if diff < 7 * DAY {
        format!("{} days ago", diff / DAY)
    } else if diff < 4 * 7 * DAY {
        format!("{} weeks ago", diff / (7 * DAY))
    } else if diff < 12 * 30 * DAY {
        format!("{} months ago", diff / (30 * DAY))
    } else {
        format!("{} years ago", diff / (365 * DAY))
    }
}

pub fn refs_expansion(graph: &GitGraph, commit: &CommitInfo, span_counter: &mut u32) -> StyledLine {
    let mut out: StyledLine = Vec::new();
    let is_head = graph.head_oid == Some(commit.oid);
    let head_branch = graph.head_branch.as_deref();
    let mut has_any = false;

    if is_head && head_branch.is_none() {
        out.extend(plain(" "));
        let sp = next_span(span_counter);
        out.extend(colored("HEAD ->", 14, sp));
        has_any = true;
        if !commit.branch_refs.is_empty() {
            out.extend(plain(" ("));
            for (i, (name, color)) in commit.branch_refs.iter().enumerate() {
                if i > 0 {
                    out.extend(plain(", "));
                }
                let sp = next_span(span_counter);
                out.extend(colored(name, *color, sp));
            }
            out.extend(plain(")"));
        }
    } else if !commit.branch_refs.is_empty() {
        out.extend(plain(" ("));
        // The current branch (if this is its tip) comes first.
        let mut order: Vec<usize> = (0..commit.branch_refs.len()).collect();
        if is_head {
            if let Some(hb) = head_branch {
                if let Some(pos) = commit.branch_refs.iter().position(|(n, _)| n == hb) {
                    order.remove(pos);
                    order.insert(0, pos);
                }
            }
        }
        for (oi, &idx) in order.iter().enumerate() {
            if oi > 0 {
                out.extend(plain(", "));
            }
            let (name, color) = &commit.branch_refs[idx];
            if is_head && head_branch == Some(name.as_str()) {
                let sp = next_span(span_counter);
                out.extend(colored("HEAD ->", 14, sp));
                out.extend(plain(" "));
            }
            let sp = next_span(span_counter);
            out.extend(colored(name, *color, sp));
        }
        out.extend(plain(")"));
        has_any = true;
    }

    if !commit.tag_refs.is_empty() {
        out.extend(plain(" "));
        let _ = has_any;
        out.extend(plain("["));
        let tag_color = commit
            .branch
            .map(|b| graph.branches[b].terminal_color)
            .unwrap_or(7);
        for (i, tag) in commit.tag_refs.iter().enumerate() {
            if i > 0 {
                out.extend(plain(", "));
            }
            let sp = next_span(span_counter);
            out.extend(colored(tag, tag_color, sp));
        }
        out.extend(plain("]"));
    }
    out
}

fn body_expansion(message: &str) -> String {
    message
        .lines()
        .skip(2)
        .map(|l| format!("{l}\n"))
        .collect()
}

fn raw_body_expansion(message: &str) -> String {
    message.lines().map(|l| format!("{l}\n")).collect()
}

enum Tok {
    Ch(StyledChar),
    Break,
}

fn placeholder_expansion(
    graph: &GitGraph,
    commit: &CommitInfo,
    code: &str,
    span_counter: &mut u32,
) -> Vec<Tok> {
    let mut toks: Vec<Tok> = Vec::new();
    let mut push_plain = |toks: &mut Vec<Tok>, s: &str| {
        for ch in s.chars() {
            toks.push(Tok::Ch(StyledChar {
                ch,
                color: None,
                span: 0,
            }));
        }
    };
    match code {
        "H" => {
            let sp = next_span(span_counter);
            for sc in colored(&commit.oid.to_string(), 11, sp) {
                toks.push(Tok::Ch(sc));
            }
        }
        "h" => {
            let sp = next_span(span_counter);
            for sc in colored(&abbrev(commit.oid), 11, sp) {
                toks.push(Tok::Ch(sc));
            }
        }
        "P" => {
            let s = commit
                .parents
                .iter()
                .map(|p| p.to_string())
                .collect::<Vec<_>>()
                .join(" ");
            push_plain(&mut toks, &s);
        }
        "p" => {
            let s = commit
                .parents
                .iter()
                .map(|p| abbrev(*p))
                .collect::<Vec<_>>()
                .join(" ");
            push_plain(&mut toks, &s);
        }
        "d" => {
            for sc in refs_expansion(graph, commit, span_counter) {
                toks.push(Tok::Ch(sc));
            }
        }
        "s" => push_plain(&mut toks, &commit.summary),
        "b" => {
            for ch in body_expansion(&commit.message).chars() {
                if ch == '\n' {
                    toks.push(Tok::Break);
                } else {
                    toks.push(Tok::Ch(StyledChar {
                        ch,
                        color: None,
                        span: 0,
                    }));
                }
            }
        }
        "B" => {
            for ch in raw_body_expansion(&commit.message).chars() {
                if ch == '\n' {
                    toks.push(Tok::Break);
                } else {
                    toks.push(Tok::Ch(StyledChar {
                        ch,
                        color: None,
                        span: 0,
                    }));
                }
            }
        }
        "an" => push_plain(&mut toks, &commit.author_name),
        "ae" => push_plain(&mut toks, &commit.author_email),
        "ad" => push_plain(&mut toks, &format_date(commit.author_time)),
        "as" => push_plain(&mut toks, &format_date_short(commit.author_time)),
        "ar" => push_plain(&mut toks, &format_date_relative(commit.author_time)),
        "cn" => push_plain(&mut toks, &commit.committer_name),
        "ce" => push_plain(&mut toks, &commit.committer_email),
        "cd" => push_plain(&mut toks, &format_date(commit.committer_time)),
        "cs" => push_plain(&mut toks, &format_date_short(commit.committer_time)),
        "cr" => push_plain(&mut toks, &format_date_relative(commit.committer_time)),
        _ => {}
    }
    toks
}

fn placeholder_plain_is_empty(graph: &GitGraph, commit: &CommitInfo, code: &str) -> bool {
    match code {
        "H" | "h" => false,
        "P" | "p" => commit.parents.is_empty(),
        "d" => {
            let is_head = graph.head_oid == Some(commit.oid);
            commit.branch_refs.is_empty()
                && commit.tag_refs.is_empty()
                && !(is_head && graph.head_branch.is_none())
        }
        "s" => commit.summary.is_empty(),
        "b" => body_expansion(&commit.message).is_empty(),
        "B" => raw_body_expansion(&commit.message).is_empty(),
        "an" => commit.author_name.is_empty(),
        "ae" => commit.author_email.is_empty(),
        "ad" | "as" | "ar" | "cd" | "cs" | "cr" => false,
        "cn" => commit.committer_name.is_empty(),
        "ce" => commit.committer_email.is_empty(),
        _ => true,
    }
}

const CODES2: [&str; 10] = ["an", "ae", "ad", "as", "ar", "cn", "ce", "cd", "cs", "cr"];
const CODES1: [char; 9] = ['H', 'h', 'P', 'p', 'd', 's', 'b', 'B', 'n'];

fn format_custom(graph: &GitGraph, commit: &CommitInfo, fmt: &str) -> Vec<StyledLine> {
    let chars: Vec<char> = fmt.chars().collect();
    let mut toks: Vec<Tok> = Vec::new();
    let mut span_counter: u32 = 0;
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] != '%' {
            toks.push(Tok::Ch(StyledChar {
                ch: chars[i],
                color: None,
                span: 0,
            }));
            i += 1;
            continue;
        }
        let mut j = i + 1;
        let mut modifier: Option<char> = None;
        if j < chars.len() && matches!(chars[j], '+' | '-' | ' ') {
            modifier = Some(chars[j]);
            j += 1;
        }
        // Resolve the placeholder code at position j.
        let mut code: Option<String> = None;
        if j + 1 < chars.len() {
            let two: String = [chars[j], chars[j + 1]].iter().collect();
            if CODES2.contains(&two.as_str()) {
                code = Some(two);
            }
        }
        if code.is_none() && j < chars.len() && CODES1.contains(&chars[j]) {
            code = Some(chars[j].to_string());
        }
        let Some(code) = code else {
            toks.push(Tok::Ch(StyledChar {
                ch: '%',
                color: None,
                span: 0,
            }));
            i += 1;
            continue;
        };
        let code_len = code.chars().count();
        if code == "n" {
            toks.push(Tok::Break);
            i = j + code_len;
            continue;
        }
        let empty = placeholder_plain_is_empty(graph, commit, &code);
        match modifier {
            Some('+') if !empty => toks.push(Tok::Break),
            Some('-') if empty => {
                while matches!(toks.last(), Some(Tok::Break)) {
                    toks.pop();
                }
            }
            Some(' ') if !empty => toks.push(Tok::Ch(StyledChar {
                ch: ' ',
                color: None,
                span: 0,
            })),
            _ => {}
        }
        let expansion = placeholder_expansion(graph, commit, &code, &mut span_counter);
        toks.extend(expansion);
        i = j + code_len;
    }

    let mut lines: Vec<StyledLine> = Vec::new();
    let mut cur: StyledLine = Vec::new();
    for tok in toks {
        match tok {
            Tok::Break => {
                lines.push(std::mem::take(&mut cur));
            }
            Tok::Ch(sc) => cur.push(sc),
        }
    }
    lines.push(cur);
    lines.retain(|l| !l.is_empty());
    lines
}

fn preset_lines(graph: &GitGraph, commit: &CommitInfo, format: &CommitFormat) -> Vec<StyledLine> {
    let mut span_counter: u32 = 0;
    match format {
        CommitFormat::Oneline => {
            let mut line: StyledLine = Vec::new();
            let sp = next_span(&mut span_counter);
            line.extend(colored(&abbrev(commit.oid), 11, sp));
            line.extend(refs_expansion(graph, commit, &mut span_counter));
            line.extend(plain(" "));
            line.extend(plain(&commit.summary));
            vec![line]
        }
        CommitFormat::Short | CommitFormat::Medium | CommitFormat::Full => {
            let mut lines: Vec<StyledLine> = Vec::new();
            let mut first: StyledLine = Vec::new();
            first.extend(plain("commit "));
            let sp = next_span(&mut span_counter);
            first.extend(colored(&commit.oid.to_string(), 11, sp));
            first.extend(refs_expansion(graph, commit, &mut span_counter));
            lines.push(first);
            if commit.parents.len() >= 2 {
                lines.push(plain(&format!(
                    "Merge: {} {}",
                    abbrev(commit.parents[0]),
                    abbrev(commit.parents[1])
                )));
            }
            lines.push(plain(&format!(
                "Author: {} <{}>",
                commit.author_name, commit.author_email
            )));
            if matches!(format, CommitFormat::Full) {
                lines.push(plain(&format!(
                    "Commit: {} <{}>",
                    commit.committer_name, commit.committer_email
                )));
            }
            if matches!(format, CommitFormat::Medium | CommitFormat::Full) {
                lines.push(plain(&format!(
                    "Date:   {}",
                    format_date(commit.author_time)
                )));
            }
            lines.push(Vec::new());
            if matches!(format, CommitFormat::Short) {
                lines.push(plain(&format!("    {}", commit.summary)));
            } else {
                for l in commit.message.lines() {
                    if l.is_empty() {
                        lines.push(Vec::new());
                    } else {
                        lines.push(plain(&format!("    {l}")));
                    }
                }
            }
            lines.push(Vec::new());
            lines
        }
        CommitFormat::Custom(_) => unreachable!(),
    }
}

pub fn format_commit(
    graph: &GitGraph,
    commit: &CommitInfo,
    format: &CommitFormat,
) -> Vec<StyledLine> {
    match format {
        CommitFormat::Custom(fmt) => format_custom(graph, commit, fmt),
        _ => preset_lines(graph, commit, format),
    }
}

// ---------------- wrapping ----------------

fn char_width(ch: char) -> usize {
    UnicodeWidthChar::width(ch).unwrap_or(0)
}

fn styled_width(chars: &[StyledChar]) -> usize {
    chars.iter().map(|c| char_width(c.ch)).sum()
}

#[derive(Debug, Clone)]
struct Unit {
    core: Vec<StyledChar>,
    trailing: Vec<StyledChar>,
}

fn indent_chars(n: usize) -> StyledLine {
    (0..n)
        .map(|_| StyledChar {
            ch: ' ',
            color: None,
            span: 0,
        })
        .collect()
}

/// Split a core into chunks of display width at most `limit` (at least one
/// character per chunk).
fn chunk_core(core: &[StyledChar], limit: usize) -> Vec<Vec<StyledChar>> {
    let mut chunks: Vec<Vec<StyledChar>> = Vec::new();
    let mut cur: Vec<StyledChar> = Vec::new();
    let mut cur_w = 0usize;
    for &sc in core {
        let w = char_width(sc.ch);
        if !cur.is_empty() && cur_w + w > limit {
            chunks.push(std::mem::take(&mut cur));
            cur_w = 0;
        }
        cur.push(sc);
        cur_w += w;
    }
    if !cur.is_empty() || chunks.is_empty() {
        chunks.push(cur);
    }
    chunks
}

fn wrap_paragraph(
    para: &[StyledChar],
    width: usize,
    indent1: usize,
    indent2: usize,
    first_overall: bool,
) -> Vec<StyledLine> {
    // Tokenise by ASCII spaces: a token is a run of non-space characters
    // plus the spaces following it.
    let mut tokens: Vec<Unit> = Vec::new();
    let mut idx = 0usize;
    while idx < para.len() {
        let core_start = idx;
        while idx < para.len() && para[idx].ch != ' ' {
            idx += 1;
        }
        let core: Vec<StyledChar> = para[core_start..idx].to_vec();
        let trail_start = idx;
        while idx < para.len() && para[idx].ch == ' ' {
            idx += 1;
        }
        let trailing: Vec<StyledChar> = para[trail_start..idx].to_vec();
        tokens.push(Unit { core, trailing });
    }
    if tokens.is_empty() {
        return Vec::new();
    }
    let has_core = tokens.iter().any(|t| !t.core.is_empty());
    if !has_core {
        return Vec::new();
    }

    // Split cores at hyphens, then break over-long fragments into chunks
    // sized to fit a subsequent line.
    let chunk_limit = {
        let l = width.saturating_sub(indent2);
        if l == 0 {
            1
        } else {
            l
        }
    };
    let mut units: Vec<Unit> = Vec::new();
    for tok in tokens {
        // fragments split after '-'
        let mut frags: Vec<Vec<StyledChar>> = Vec::new();
        let mut cur: Vec<StyledChar> = Vec::new();
        for sc in &tok.core {
            cur.push(*sc);
            if sc.ch == '-' {
                frags.push(std::mem::take(&mut cur));
            }
        }
        if !cur.is_empty() || frags.is_empty() {
            frags.push(cur);
        }
        let nfrags = frags.len();
        for (fi, frag) in frags.into_iter().enumerate() {
            let trailing = if fi == nfrags - 1 {
                tok.trailing.clone()
            } else {
                Vec::new()
            };
            if styled_width(&frag) > chunk_limit {
                let chunks = chunk_core(&frag, chunk_limit);
                let nch = chunks.len();
                for (ci, ch) in chunks.into_iter().enumerate() {
                    units.push(Unit {
                        core: ch,
                        trailing: if ci == nch - 1 {
                            trailing.clone()
                        } else {
                            Vec::new()
                        },
                    });
                }
            } else {
                units.push(Unit {
                    core: frag,
                    trailing,
                });
            }
        }
    }

    let mut out: Vec<StyledLine> = Vec::new();
    let mut current: Vec<Unit> = Vec::new();
    let mut current_width = 0usize;
    let mut line_indent = if first_overall { indent1 } else { indent2 };
    // Whether the fresh-line exception may still be used to emit one blank
    // line (see module-level analysis in tests).
    let mut may_emit_blank = true;

    let emit = |out: &mut Vec<StyledLine>, units: &[Unit], indent: usize| {
        let mut line = indent_chars(indent);
        for (ui, u) in units.iter().enumerate() {
            line.extend(u.core.iter().copied());
            if ui + 1 < units.len() {
                line.extend(u.trailing.iter().copied());
            }
        }
        out.push(line);
    };

    for unit in units {
        let unit_w = styled_width(&unit.core);
        let capacity = width.saturating_sub(line_indent);
        if current_width + unit_w > capacity {
            if !current.is_empty() {
                emit(&mut out, &current, line_indent);
                current = Vec::new();
                current_width = 0;
                line_indent = indent2;
                may_emit_blank = false;
            } else if may_emit_blank {
                // First unit does not fit even on an empty line: emit the
                // (blank) line and move to a subsequent line.
                out.push(indent_chars(line_indent));
                line_indent = indent2;
                may_emit_blank = false;
            }
            // Fall through and place the unit on the (new) line even if it
            // nominally exceeds the capacity.
        }
        current_width += unit_w + styled_width(&unit.trailing);
        current.push(unit);
    }
    if !current.is_empty() {
        if current.iter().any(|u| !u.core.is_empty()) {
            emit(&mut out, &current, line_indent);
        } else if !may_emit_blank {
            // A trailing run of empty-core units after content is dropped.
        }
    }
    out
}

pub fn wrap_one_line(
    line: &StyledLine,
    width: usize,
    indent1: usize,
    indent2: usize,
) -> Vec<StyledLine> {
    if line.is_empty() {
        return vec![Vec::new()];
    }
    // Split into paragraphs at hard newlines, mimicking Rust's
    // `str::lines` (a final trailing newline yields no extra paragraph).
    let mut paragraphs: Vec<Vec<StyledChar>> = Vec::new();
    let mut cur: Vec<StyledChar> = Vec::new();
    for &sc in line.iter() {
        if sc.ch == '\n' {
            paragraphs.push(std::mem::take(&mut cur));
        } else {
            cur.push(sc);
        }
    }
    let ends_with_newline = line.last().map(|c| c.ch) == Some('\n');
    if !ends_with_newline {
        paragraphs.push(cur);
    } else if paragraphs.is_empty() {
        paragraphs.push(cur);
    }
    // Note: a paragraph consisting of a single trailing '\r' from "\r\n"
    // loses it, like `str::lines`.
    for p in paragraphs.iter_mut() {
        if p.last().map(|c| c.ch) == Some('\r') {
            // Only strip when it came from a "\r\n" pair, i.e. when the
            // paragraph was terminated by '\n'. This is close enough: a
            // lone trailing CR in the last paragraph was not followed by
            // a newline, but such text is vanishingly rare here.
            p.pop();
        }
    }

    let mut out: Vec<StyledLine> = Vec::new();
    let mut first_overall = true;
    for para in &paragraphs {
        if para.is_empty() {
            let ind = if first_overall { indent1 } else { indent2 };
            out.push(indent_chars(ind));
            first_overall = false;
            continue;
        }
        let sub = wrap_paragraph(para, width, indent1, indent2, first_overall);
        out.extend(sub);
        first_overall = false;
    }
    out
}

pub fn effective_wrap_width(
    wrap: &WrapSettings,
    num_columns: usize,
    stdout_terminal_width: Option<usize>,
) -> Option<usize> {
    match wrap.width {
        WrapWidth::Fixed(w) => Some(w),
        WrapWidth::None => None,
        WrapWidth::Auto => {
            let tw = stdout_terminal_width?;
            let graph_width = 2 * num_columns + 3;
            let w = tw.saturating_sub(graph_width);
            if w >= 40 {
                Some(w)
            } else {
                None
            }
        }
    }
}

pub fn wrap_commit_lines(
    lines: Vec<StyledLine>,
    wrap: &WrapSettings,
    effective_width: Option<usize>,
) -> Vec<StyledLine> {
    let Some(width) = effective_width else {
        return lines;
    };
    let mut out: Vec<StyledLine> = Vec::new();
    for line in &lines {
        out.extend(wrap_one_line(line, width, wrap.indent1, wrap.indent2));
    }
    out
}

pub fn styled_plain_text(line: &StyledLine) -> String {
    line.iter().map(|c| c.ch).collect()
}
