fn fmt_num(v: f64) -> String {
    if v.fract() == 0.0 {
        format!("{}", v as i64)
    } else {
        format!("{v}")
    }
}

fn esc_attr(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn svg_line(x1: f64, y1: f64, x2: f64, y2: f64, color: &str, width: usize) -> String {
    format!(
        "<line stroke=\"{}\" stroke-width=\"{}\" x1=\"{}\" x2=\"{}\" y1=\"{}\" y2=\"{}\"/>",
        esc_attr(color),
        width,
        fmt_num(x1),
        fmt_num(x2),
        fmt_num(y1),
        fmt_num(y2)
    )
}

fn svg_path_primary(x1: f64, y1: f64, x2: f64, y2: f64, color: &str) -> String {
    let y_curve = y2 - 7.5;
    let d = format!(
        "M{},{} L{},{} Q{},{} {},{} Q{},{} {},{} L{},{}",
        fmt_num(x1),
        fmt_num(y1),
        fmt_num(x1),
        fmt_num(y2 - 15.0),
        fmt_num(x1),
        fmt_num(y_curve),
        fmt_num((x1 + x2) / 2.0),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve + 7.5),
        fmt_num(x2),
        fmt_num(y2)
    );
    format!(
        "<path d=\"{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>",
        esc_attr(&d),
        esc_attr(color)
    )
}

fn svg_path_secondary(x1: f64, y1: f64, x2: f64, y2: f64, color: &str) -> String {
    let y_curve = y1 + 7.5;
    let d = format!(
        "M{},{} L{},{} Q{},{} {},{} Q{},{} {},{} L{},{}",
        fmt_num(x1),
        fmt_num(y1),
        fmt_num(x1),
        fmt_num(y1),
        fmt_num(x1),
        fmt_num(y_curve),
        fmt_num((x1 + x2) / 2.0),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve + 7.5),
        fmt_num(x2),
        fmt_num(y2)
    );
    format!(
        "<path d=\"{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>",
        esc_attr(&d),
        esc_attr(color)
    )
}

pub fn print_svg(graph: &GitGraph, debug: bool) -> String {
    let n = graph.commits.len();
    let cols = graph.num_columns.max(1);
    let width = (cols + 1) * 15;
    let height = (n + 2) * 15;
    let mut elements: Vec<String> = Vec::new();

    if debug {
        for b in &graph.branches {
            if let (Some(s), Some(e)) = b.range {
                if b.column == 99 {
                    continue;
                }
                let x = ((b.column + 1) * 15) as f64;
                elements.push(svg_line(
                    x,
                    ((s + 1) * 15) as f64,
                    x,
                    ((e + 1) * 15) as f64,
                    "cyan",
                    5,
                ));
            }
        }
    }

    let coord = |idx: usize, col: usize| -> (f64, f64) {
        (((col + 1) * 15) as f64, ((idx + 1) * 15) as f64)
    };

    for (i, c) in graph.commits.iter().enumerate() {
        let own_col = col_of(graph, i);
        let (x, y) = coord(i, own_col);
        let branch_idx = c.branch.unwrap_or(0);
        let own_color = graph
            .branches
            .get(branch_idx)
            .map(|b| b.svg_color.clone())
            .unwrap_or_else(|| "gray".to_owned());
        if !c.parents.is_empty() {
            let target = graph.oid_index.get(&c.parents[0]).copied();
            let (tx, ty) = match target {
                Some(t) => coord(t, col_of(graph, t)),
                None => (x, ((n + 1) * 15) as f64),
            };
            if tx == x {
                elements.push(svg_line(x, y, tx, ty, &own_color, 1));
            } else {
                elements.push(svg_path_primary(x, y, tx, ty, &own_color));
            }
        }
        if c.parents.len() >= 2 {
            let target = graph.oid_index.get(&c.parents[1]).copied();
            let (tx, ty, tcolor) = match target {
                Some(t) => {
                    let tb = graph.commits[t].branch.unwrap_or(branch_idx);
                    (
                        ((col_of(graph, t) + 1) * 15) as f64,
                        ((t + 1) * 15) as f64,
                        graph
                            .branches
                            .get(tb)
                            .map(|b| b.svg_color.clone())
                            .unwrap_or_else(|| "gray".to_owned()),
                    )
                }
                None => (x, ((n + 1) * 15) as f64, own_color.clone()),
            };
            if tx == x {
                elements.push(svg_line(x, y, tx, ty, &tcolor, 1));
            } else {
                elements.push(svg_path_secondary(x, y, tx, ty, &tcolor));
            }
        }
        let fill = if c.is_merge { "white" } else { &own_color };
        elements.push(format!(
            "<circle cx=\"{}\" cy=\"{}\" fill=\"{}\" r=\"4\" stroke=\"{}\" stroke-width=\"1\"/>",
            fmt_num(x),
            fmt_num(y),
            esc_attr(fill),
            esc_attr(&own_color)
        ));
    }

    if elements.is_empty() {
        format!(
            "<svg height=\"{height}\" viewBox=\"0 0 {width} {height}\" width=\"{width}\" xmlns=\"http://www.w3.org/2000/svg\"/>\n"
        )
    } else {
        let mut out = format!(
            "<svg height=\"{height}\" viewBox=\"0 0 {width} {height}\" width=\"{width}\" xmlns=\"http://www.w3.org/2000/svg\">\n"
        );
        for e in elements {
            out.push_str(&e);
            out.push('\n');
        }
        out.push_str("</svg>\n");
        out
    }
}
