use crate::format::{
    format_commit, wrap_commit_lines, CommitFormat, StyledChar, StyledLine,
};
use crate::graph::GitGraph;
use crate::settings::{Style, WrapSettings, DOWN, LEFT, RIGHT, UP};
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CellKind {
    Space,
    Mask(u8),
    Dot(bool),
}

#[derive(Debug, Clone, Copy)]
struct VCell {
    kind: CellKind,
    color: Option<u8>,
}

#[derive(Debug, Clone, Copy)]
enum VConn {
    Space,
    Dash(u8),
    Arrow(char, u8),
}

#[derive(Debug, Clone)]
struct VLine {
    cells: Vec<VCell>,
    conns: Vec<VConn>,
    text: StyledLine,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SlotKind {
    Dot,
    Text,
    Inserted,
}

#[derive(Debug, Clone)]
struct Slot {
    kind: SlotKind,
    commit: usize,
    text: StyledLine,
}

#[derive(Debug, Clone)]
struct PrimaryEdge {
    source: usize,
    source_col: usize,
    target: Option<usize>,
    target_eff: usize,
    target_col: usize,
    branch: usize,
    join_slot: Option<usize>,
}

#[derive(Debug, Clone)]
struct SecondaryEdge {
    source: usize,
    source_col: usize,
    target: Option<usize>,
    target_eff: usize,
    target_col: usize,
    target_branch: usize,
    event_slot: Option<usize>,
}

#[derive(Debug, Clone)]
enum HEvent {
    PrimaryJoin {
        target: usize,
        target_col: usize,
        edges: Vec<usize>,
    },
    Merge {
        secondary: usize,
    },
}

#[derive(Debug, Clone)]
struct Segment {
    col: usize,
    start: usize,
    end: usize, // slot index of the ending slot, or slots.len() as a sentinel
    color: u8,
    priority: usize, // 0 primary A, 1 primary B, 2 secondary
}

fn panic_on_empty(count: usize) -> ! {
    let v = vec![0usize; count];
    let _x = v[count];
    unreachable!()
}

fn col_of(graph: &GitGraph, commit_idx: usize) -> usize {
    graph.branch_column_of_commit(commit_idx)
}

pub fn print_text(
    graph: &GitGraph,
    format: &CommitFormat,
    wrap: &WrapSettings,
    effective_width: Option<usize>,
    style: Style,
    sparse: bool,
    reverse: bool,
    use_color: bool,
) -> String {
    let n = graph.commits.len();
    let cols = graph.num_columns;

    let mut per_commit_lines: Vec<Vec<StyledLine>> = Vec::with_capacity(n);
    for c in &graph.commits {
        let formatted = format_commit(graph, c, format);
        per_commit_lines.push(wrap_commit_lines(formatted, wrap, effective_width));
    }

    // Edges.
    let mut primaries: Vec<PrimaryEdge> = Vec::new();
    let mut secondaries: Vec<SecondaryEdge> = Vec::new();
    for (i, c) in graph.commits.iter().enumerate() {
        let own_col = col_of(graph, i);
        if !c.parents.is_empty() {
            let target = graph.oid_index.get(&c.parents[0]).copied();
            let target_col = target.map(|t| col_of(graph, t)).unwrap_or(own_col);
            primaries.push(PrimaryEdge {
                source: i,
                source_col: own_col,
                target,
                target_eff: target.unwrap_or(n),
                target_col,
                branch: c.branch.unwrap_or(0),
                join_slot: None,
            });
        }
        if c.parents.len() >= 2 {
            let target = graph.oid_index.get(&c.parents[1]).copied();
            let target_col = target.map(|t| col_of(graph, t)).unwrap_or(own_col);
            let target_branch = target
                .and_then(|t| graph.commits[t].branch)
                .unwrap_or_else(|| c.branch.unwrap_or(0));
            secondaries.push(SecondaryEdge {
                source: i,
                source_col: own_col,
                target,
                target_eff: target.unwrap_or(n),
                target_col,
                target_branch,
                event_slot: None,
            });
        }
    }
    let primary_by_source: HashMap<usize, usize> = primaries
        .iter()
        .enumerate()
        .map(|(i, e)| (e.source, i))
        .collect();
    let secondary_by_source: HashMap<usize, usize> = secondaries
        .iter()
        .enumerate()
        .map(|(i, e)| (e.source, i))
        .collect();

    // Primary join groups, keyed by target commit.
    let mut join_groups: HashMap<usize, Vec<usize>> = HashMap::new();
    for (ei, e) in primaries.iter().enumerate() {
        if let Some(t) = e.target {
            if e.target_col != e.source_col {
                join_groups.entry(t).or_default().push(ei);
            }
        }
    }

    // Determine which commits need an inserted slot after their dot slot.
    let mut needs_inserted = vec![false; n];
    // Placement records: (event, placement) where placement 0=dot,1=after dot
    #[derive(Clone)]
    struct PlacedEvent {
        event: HEvent,
        commit: usize, // commit whose dot/after-dot slot it uses
        after_dot: bool,
    }
    let mut placed: Vec<PlacedEvent> = Vec::new();

    for (i, _c) in graph.commits.iter().enumerate() {
        // Sparse/compact merge event for this commit.
        if let Some(&si) = secondary_by_source.get(&i) {
            let e = &secondaries[si];
            if e.target.is_some() && e.target_col != e.source_col {
                if sparse {
                    placed.push(PlacedEvent {
                        event: HEvent::Merge { secondary: si },
                        commit: i,
                        after_dot: true,
                    });
                    if per_commit_lines.get(i).map(|l| l.len()).unwrap_or(0) <= 1 {
                        needs_inserted[i] = true;
                    }
                } else {
                    placed.push(PlacedEvent {
                        event: HEvent::Merge { secondary: si },
                        commit: i,
                        after_dot: false,
                    });
                }
            }
        }
        // Primary joins targeting the next commit.
        if i + 1 < n {
            if let Some(group) = join_groups.get(&(i + 1)) {
                let mut lo = usize::MAX;
                let mut hi = 0usize;
                for &ei in group {
                    let e = &primaries[ei];
                    lo = lo.min(e.source_col).min(e.target_col);
                    hi = hi.max(e.source_col).max(e.target_col);
                }
                let dot_col = col_of(graph, i);
                let after_dot = dot_col >= lo && dot_col <= hi;
                if after_dot && per_commit_lines.get(i).map(|l| l.len()).unwrap_or(0) <= 1 {
                    needs_inserted[i] = true;
                }
                placed.push(PlacedEvent {
                    event: HEvent::PrimaryJoin {
                        target: i + 1,
                        target_col: primaries[group[0]].target_col,
                        edges: group.clone(),
                    },
                    commit: i,
                    after_dot,
                });
            }
        }
    }

    // Build slots.
    let mut slots: Vec<Slot> = Vec::new();
    let mut dot_slot: HashMap<usize, usize> = HashMap::new();
    let mut after_dot_slot: HashMap<usize, usize> = HashMap::new();
    for i in 0..n {
        if per_commit_lines[i].is_empty() {
            panic_on_empty(slots.len());
        }
        dot_slot.insert(i, slots.len());
        slots.push(Slot {
            kind: SlotKind::Dot,
            commit: i,
            text: per_commit_lines[i][0].clone(),
        });
        if needs_inserted[i] {
            after_dot_slot.insert(i, slots.len());
            slots.push(Slot {
                kind: SlotKind::Inserted,
                commit: i,
                text: Vec::new(),
            });
        }
        for li in 1..per_commit_lines[i].len() {
            if li == 1 && !needs_inserted[i] {
                after_dot_slot.insert(i, slots.len());
            }
            slots.push(Slot {
                kind: SlotKind::Text,
                commit: i,
                text: per_commit_lines[i][li].clone(),
            });
        }
    }
    let total_slots = slots.len();

    // Assign events to slots.
    let mut events_by_slot: HashMap<usize, Vec<HEvent>> = HashMap::new();
    for pe in placed {
        let slot_idx = if pe.after_dot {
            match after_dot_slot.get(&pe.commit) {
                Some(s) => *s,
                None => dot_slot[&pe.commit],
            }
        } else {
            dot_slot[&pe.commit]
        };
        match &pe.event {
            HEvent::PrimaryJoin { edges, .. } => {
                for &ei in edges {
                    primaries[ei].join_slot = Some(slot_idx);
                }
            }
            HEvent::Merge { secondary } => {
                secondaries[*secondary].event_slot = Some(slot_idx);
            }
        }
        events_by_slot.entry(slot_idx).or_default().push(pe.event);
    }

    // Segments.
    let mut segments: Vec<Segment> = Vec::new();
    let branch_color = |b: usize| -> u8 {
        graph
            .branches
            .get(b)
            .map(|br| br.terminal_color)
            .unwrap_or(7)
    };
    for e in &primaries {
        let start = dot_slot[&e.source];
        if e.target_col != e.source_col {
            let join = e.join_slot.unwrap_or(start);
            segments.push(Segment {
                col: e.source_col,
                start,
                end: join,
                color: branch_color(e.branch),
                priority: 0,
            });
            if let Some(t) = e.target {
                segments.push(Segment {
                    col: e.target_col,
                    start: join,
                    end: dot_slot[&t],
                    color: branch_color(graph.commits[t].branch.unwrap_or(e.branch)),
                    priority: 1,
                });
            }
        } else {
            let end = e.target.map(|t| dot_slot[&t]).unwrap_or(total_slots);
            segments.push(Segment {
                col: e.source_col,
                start,
                end,
                color: branch_color(e.branch),
                priority: 0,
            });
        }
    }
    for e in &secondaries {
        // Only segments that correspond to a visible merge edge (or a stub
        // in the same column) matter; including a same-column stub is
        // harmless as it duplicates the primary segment's column.
        let start = if sparse {
            match e.event_slot {
                Some(s) => s,
                None => dot_slot[&e.source],
            }
        } else {
            dot_slot[&e.source]
        };
        let end = e.target.map(|t| dot_slot[&t]).unwrap_or(total_slots);
        if end > start || e.target.is_some() {
            segments.push(Segment {
                col: e.target_col,
                start,
                end,
                color: branch_color(e.target_branch),
                priority: 2,
            });
        }
    }

    // Build visual lines.
    let mut vlines: Vec<VLine> = Vec::with_capacity(total_slots);
    for (si, slot) in slots.iter().enumerate() {
        let mut cells: Vec<VCell> = Vec::with_capacity(cols);
        let events_here: &[HEvent] = events_by_slot
            .get(&si)
            .map(|v| v.as_slice())
            .unwrap_or(&[]);

        // Horizontal coverage per column/connector.
        let mut hseg_for_connector = |conn: usize| -> Vec<(usize, usize, usize, u8, bool, Option<usize>)> {
            // returns (lo,hi,source_col,color,is_merge,secondary_idx)
            let mut res = Vec::new();
            for ev in events_here {
                match ev {
                    HEvent::PrimaryJoin { edges, .. } => {
                        for &ei in edges {
                            let e = &primaries[ei];
                            let lo = e.source_col.min(e.target_col);
                            let hi = e.source_col.max(e.target_col);
                            if lo <= conn && hi >= conn + 1 {
                                res.push((
                                    lo,
                                    hi,
                                    e.source_col,
                                    branch_color(e.branch),
                                    false,
                                    None,
                                ));
                            }
                        }
                    }
                    HEvent::Merge { secondary } => {
                        let e = &secondaries[*secondary];
                        let lo = e.source_col.min(e.target_col);
                        let hi = e.source_col.max(e.target_col);
                        if lo <= conn && hi >= conn + 1 {
                            res.push((
                                lo,
                                hi,
                                e.source_col,
                                branch_color(e.target_branch),
                                true,
                                Some(*secondary),
                            ));
                        }
                    }
                }
            }
            res
        };

        for c in 0..cols {
            if slot.kind == SlotKind::Dot && col_of(graph, slot.commit) == c {
                let commit = &graph.commits[slot.commit];
                cells.push(VCell {
                    kind: CellKind::Dot(commit.is_merge),
                    color: Some(branch_color(commit.branch.unwrap_or(0))),
                });
                continue;
            }
            let mut up = false;
            let mut down = false;
            let mut covering: Vec<&Segment> = Vec::new();
            for seg in &segments {
                if seg.col != c {
                    continue;
                }
                if si >= seg.start && si <= seg.end {
                    covering.push(seg);
                    if si > seg.start {
                        up = true;
                    }
                    if si < seg.end {
                        down = true;
                    }
                }
            }
            let left = c > 0 && !hseg_for_connector(c - 1).is_empty();
            let right = c + 1 < cols && !hseg_for_connector(c).is_empty();
            let mut mask = 0u8;
            if up {
                mask |= UP;
            }
            if down {
                mask |= DOWN;
            }
            if left {
                mask |= LEFT;
            }
            if right {
                mask |= RIGHT;
            }
            if mask == 0 {
                cells.push(VCell {
                    kind: CellKind::Space,
                    color: None,
                });
                continue;
            }
            // Colour selection.
            let mut color: Option<u8> = None;
            // Target of a primary join or a merge here?
            for ev in events_here {
                match ev {
                    HEvent::PrimaryJoin {
                        target,
                        target_col,
                        ..
                    } if *target_col == c => {
                        color = Some(branch_color(
                            graph.commits[*target].branch.unwrap_or(0),
                        ));
                    }
                    HEvent::Merge { secondary }
                        if secondaries[*secondary].target_col == c =>
                    {
                        color = Some(branch_color(secondaries[*secondary].target_branch));
                    }
                    HEvent::Merge { secondary }
                        if sparse && secondaries[*secondary].source_col == c =>
                    {
                        color =
                            Some(branch_color(graph.commits[secondaries[*secondary].source]
                                .branch
                                .unwrap_or(0)));
                    }
                    _ => {}
                }
            }
            if color.is_none() {
                // A vertical trace that continues downwards keeps its colour.
                let mut continuing: Vec<&Segment> = covering
                    .iter()
                    .copied()
                    .filter(|seg| si < seg.end && seg.priority == 0)
                    .collect();
                continuing.sort_by_key(|s| s.priority);
                if let Some(seg) = continuing.first() {
                    color = Some(seg.color);
                }
            }
            if color.is_none() && (left || right) {
                // Colour of the horizontal segment through this cell.
                // Gather candidates from connectors on both sides.
                let mut cands: Vec<(usize, usize, usize, u8, bool, Option<usize>)> = Vec::new();
                if left {
                    cands.extend(hseg_for_connector(c - 1));
                }
                if right {
                    cands.extend(hseg_for_connector(c));
                }
                // Prefer a merge segment; otherwise the primary segment
                // whose source is furthest away.
                if let Some(m) = cands.iter().find(|x| x.4) {
                    color = Some(m.3);
                } else if !cands.is_empty() {
                    // target column of the group determines the side; use
                    // the candidate with maximal distance to `c`'s side by
                    // preferring the source furthest from the midpoint.
                    let mut best = cands[0];
                    for cand in &cands[1..] {
                        let d_best = (best.2 as i64 - c as i64).abs();
                        let d_cand = (cand.2 as i64 - c as i64).abs();
                        if d_cand > d_best {
                            best = *cand;
                        }
                    }
                    color = Some(best.3);
                }
            }
            if color.is_none() {
                let mut sorted = covering.clone();
                sorted.sort_by_key(|s| s.priority);
                if let Some(seg) = sorted.first() {
                    color = Some(seg.color);
                }
            }
            cells.push(VCell {
                kind: CellKind::Mask(mask),
                color,
            });
        }

        let mut conns: Vec<VConn> = Vec::new();
        for conn in 0..cols.saturating_sub(1) {
            let cands = hseg_for_connector(conn);
            if cands.is_empty() {
                conns.push(VConn::Space);
                continue;
            }
            if let Some(m) = cands.iter().find(|x| x.4) {
                let sec = &secondaries[m.5.unwrap()];
                let adjacent_to_source = (sec.target_col > sec.source_col && conn == sec.source_col)
                    || (sec.target_col < sec.source_col && conn + 1 == sec.source_col);
                if adjacent_to_source {
                    let ch = if sec.target_col > sec.source_col {
                        '<'
                    } else {
                        '>'
                    };
                    conns.push(VConn::Arrow(ch, m.3));
                } else {
                    conns.push(VConn::Dash(m.3));
                }
            } else {
                // Furthest source from the join target on this side wins.
                // The target column is the same for all edges of a group;
                // recover it from the events here.
                let mut target_col: Option<usize> = None;
                for ev in events_here {
                    if let HEvent::PrimaryJoin { target_col: tc, .. } = ev {
                        target_col = Some(*tc);
                    }
                }
                let mut best = cands[0];
                if let Some(tc) = target_col {
                    for cand in &cands[1..] {
                        let d_best = (best.2 as i64 - tc as i64).abs();
                        let d_cand = (cand.2 as i64 - tc as i64).abs();
                        if d_cand > d_best {
                            best = *cand;
                        }
                    }
                }
                conns.push(VConn::Dash(best.3));
            }
        }

        vlines.push(VLine {
            cells,
            conns,
            text: slot.text.clone(),
        });
    }

    if reverse {
        vlines = reverse_vlines(vlines);
    }

    render_vlines(&vlines, style, use_color, cols)
}

fn rotate_mask(mask: u8) -> u8 {
    let mut m = 0u8;
    if mask & UP != 0 {
        m |= DOWN;
    }
    if mask & DOWN != 0 {
        m |= UP;
    }
    if mask & LEFT != 0 {
        m |= RIGHT;
    }
    if mask & RIGHT != 0 {
        m |= LEFT;
    }
    m
}

fn reverse_vlines(lines: Vec<VLine>) -> Vec<VLine> {
    let mut out: Vec<VLine> = Vec::with_capacity(lines.len());
    for line in lines.iter().rev() {
        let cols = line.cells.len();
        let mut cells: Vec<VCell> = Vec::with_capacity(cols);
        for c in 0..cols {
            let old = line.cells[cols - 1 - c];
            let kind = match old.kind {
                CellKind::Mask(m) => CellKind::Mask(rotate_mask(m)),
                other => other,
            };
            cells.push(VCell {
                kind,
                color: old.color,
            });
        }
        let mut conns: Vec<VConn> = Vec::new();
        for conn in 0..line.conns.len() {
            let old = line.conns[line.conns.len() - 1 - conn];
            let nc = match old {
                VConn::Arrow('<', col) => VConn::Arrow('>', col),
                VConn::Arrow('>', col) => VConn::Arrow('<', col),
                other => other,
            };
            conns.push(nc);
        }
        out.push(VLine {
            cells,
            conns,
            text: line.text.clone(),
        });
    }
    out
}

fn paint_char(out: &mut String, ch: char, color: Option<u8>, use_color: bool) {
    if use_color {
        if let Some(c) = color {
            out.push_str(&format!("\x1b[38;5;{c}m{ch}\x1b[0m"));
            return;
        }
    }
    out.push(ch);
}

fn render_styled_text(line: &[StyledChar], use_color: bool) -> String {
    let mut out = String::new();
    if !use_color {
        for sc in line {
            out.push(sc.ch);
        }
        return out;
    }
    let mut i = 0usize;
    while i < line.len() {
        let mut j = i + 1;
        while j < line.len() && line[j].color == line[i].color && line[j].span == line[i].span {
            j += 1;
        }
        let seg: String = line[i..j].iter().map(|c| c.ch).collect();
        if let Some(c) = line[i].color {
            out.push_str(&format!("\x1b[38;5;{c}m{seg}\x1b[0m"));
        } else {
            out.push_str(&seg);
        }
        i = j;
    }
    out
}

fn render_vlines(lines: &[VLine], style: Style, use_color: bool, cols: usize) -> String {
    let mut out = String::new();
    for line in lines {
        out.push(' ');
        for c in 0..cols {
            let cell = line.cells.get(c).copied().unwrap_or(VCell {
                kind: CellKind::Space,
                color: None,
            });
            let (ch, color) = match cell.kind {
                CellKind::Space => (' ', None),
                CellKind::Mask(m) => (style.glyph(m), cell.color),
                CellKind::Dot(is_merge) => (style.dot(is_merge), cell.color),
            };
            paint_char(&mut out, ch, color, use_color);
            if c + 1 < cols {
                let conn = line.conns.get(c).copied().unwrap_or(VConn::Space);
                let (ch, color) = match conn {
                    VConn::Space => (' ', None),
                    VConn::Dash(col) => (style.horizontal(), Some(col)),
                    VConn::Arrow(ch, col) => (ch, Some(col)),
                };
                paint_char(&mut out, ch, color, use_color);
            }
        }
        out.push_str("  ");
        out.push_str(&render_styled_text(&line.text, use_color));
        out.push('\n');
    }
    out
}

// ---------------- SVG ----------------

fn fmt_num(v: f64) -> String {
    if v.fract() == 0.0 {
        format!("{}", v as i64)
    } else {
        format!("{v}")
    }
}

fn esc_attr(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn svg_line(x1: f64, y1: f64, x2: f64, y2: f64, color: &str, width: usize) -> String {
    format!(
        "<line stroke=\"{}\" stroke-width=\"{}\" x1=\"{}\" x2=\"{}\" y1=\"{}\" y2=\"{}\"/>",
        esc_attr(color),
        width,
        fmt_num(x1),
        fmt_num(x2),
        fmt_num(y1),
        fmt_num(y2)
    )
}

fn svg_path_primary(x1: f64, y1: f64, x2: f64, y2: f64, color: &str) -> String {
    let y_curve = y2 - 7.5;
    let d = format!(
        "M{},{} L{},{} Q{},{} {},{} Q{},{} {},{} L{},{}",
        fmt_num(x1),
        fmt_num(y1),
        fmt_num(x1),
        fmt_num(y2 - 15.0),
        fmt_num(x1),
        fmt_num(y_curve),
        fmt_num((x1 + x2) / 2.0),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve + 7.5),
        fmt_num(x2),
        fmt_num(y2)
    );
    format!(
        "<path d=\"{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>",
        esc_attr(&d),
        esc_attr(color)
    )
}

fn svg_path_secondary(x1: f64, y1: f64, x2: f64, y2: f64, color: &str) -> String {
    let y_curve = y1 + 7.5;
    let d = format!(
        "M{},{} L{},{} Q{},{} {},{} Q{},{} {},{} L{},{}",
        fmt_num(x1),
        fmt_num(y1),
        fmt_num(x1),
        fmt_num(y1),
        fmt_num(x1),
        fmt_num(y_curve),
        fmt_num((x1 + x2) / 2.0),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve),
        fmt_num(x2),
        fmt_num(y_curve + 7.5),
        fmt_num(x2),
        fmt_num(y2)
    );
    format!(
        "<path d=\"{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>",
        esc_attr(&d),
        esc_attr(color)
    )
}

pub fn print_svg(graph: &GitGraph, debug: bool) -> String {
    let n = graph.commits.len();
    let cols = graph.num_columns.max(1);
    let width = (cols + 1) * 15;
    let height = (n + 2) * 15;
    let mut elements: Vec<String> = Vec::new();

    if debug {
        for b in &graph.branches {
            if let (Some(s), Some(e)) = b.range {
                if b.column == 99 {
                    continue;
                }
                let x = ((b.column + 1) * 15) as f64;
                elements.push(svg_line(
                    x,
                    ((s + 1) * 15) as f64,
                    x,
                    ((e + 1) * 15) as f64,
                    "cyan",
                    5,
                ));
            }
        }
    }

    let coord = |idx: usize, col: usize| -> (f64, f64) {
        (((col + 1) * 15) as f64, ((idx + 1) * 15) as f64)
    };

    for (i, c) in graph.commits.iter().enumerate() {
        let own_col = col_of(graph, i);
        let (x, y) = coord(i, own_col);
        let branch_idx = c.branch.unwrap_or(0);
        let own_color = graph
            .branches
            .get(branch_idx)
            .map(|b| b.svg_color.clone())
            .unwrap_or_else(|| "gray".to_owned());
        if !c.parents.is_empty() {
            let target = graph.oid_index.get(&c.parents[0]).copied();
            let (tx, ty) = match target {
                Some(t) => coord(t, col_of(graph, t)),
                None => (x, ((n + 1) * 15) as f64),
            };
            if tx == x {
                elements.push(svg_line(x, y, tx, ty, &own_color, 1));
            } else {
                elements.push(svg_path_primary(x, y, tx, ty, &own_color));
            }
        }
        if c.parents.len() >= 2 {
            let target = graph.oid_index.get(&c.parents[1]).copied();
            let (tx, ty, tcolor) = match target {
                Some(t) => {
                    let tb = graph.commits[t].branch.unwrap_or(branch_idx);
                    (
                        ((col_of(graph, t) + 1) * 15) as f64,
                        ((t + 1) * 15) as f64,
                        graph
                            .branches
                            .get(tb)
                            .map(|b| b.svg_color.clone())
                            .unwrap_or_else(|| "gray".to_owned()),
                    )
                }
                None => (x, ((n + 1) * 15) as f64, own_color.clone()),
            };
            if tx == x {
                elements.push(svg_line(x, y, tx, ty, &tcolor, 1));
            } else {
                elements.push(svg_path_secondary(x, y, tx, ty, &tcolor));
            }
        }
        let fill = if c.is_merge { "white" } else { &own_color };
        elements.push(format!(
            "<circle cx=\"{}\" cy=\"{}\" fill=\"{}\" r=\"4\" stroke=\"{}\" stroke-width=\"1\"/>",
            fmt_num(x),
            fmt_num(y),
            esc_attr(fill),
            esc_attr(&own_color)
        ));
    }

    if elements.is_empty() {
        format!(
            "<svg height=\"{height}\" viewBox=\"0 0 {width} {height}\" width=\"{width}\" xmlns=\"http://www.w3.org/2000/svg\"/>\n"
        )
    } else {
        let mut out = format!(
            "<svg height=\"{height}\" viewBox=\"0 0 {width} {height}\" width=\"{width}\" xmlns=\"http://www.w3.org/2000/svg\">\n"
        );
        for e in elements {
            out.push_str(&e);
            out.push('\n');
        }
        out.push_str("</svg>\n");
        out
    }
}
