        .arg(
            Arg::new("wrap")
                .short('w')
                .long("wrap")
                .value_name("wrap")
                .num_args(0..=3)
                .help(WRAP_HELP)
                .long_help(WRAP_LONG_HELP),
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("format")
                .help(FORMAT_HELP)
                .long_help(FORMAT_LONG_HELP),
        )
        .arg(
            Arg::new("reverse")
                .short('r')
                .long("reverse")
                .action(ArgAction::SetTrue)
                .help("Reverse the order of commits."),
        )
        .arg(
            Arg::new("local")
                .short('l')
                .long("local")
                .action(ArgAction::SetTrue)
                .help("Show only local branches, no remotes."),
        )
        .arg(
            Arg::new("svg")
                .long("svg")
                .action(ArgAction::SetTrue)
                .help("Render graph as SVG instead of text-based."),
        )
        .arg(
            Arg::new("debug")
                .short('d')
                .long("debug")
                .action(ArgAction::SetTrue)
                .help("Additional debug output and graphics."),
        )
        .arg(
            Arg::new("sparse")
                .short('S')
                .long("sparse")
                .action(ArgAction::SetTrue)
                .help("Print a less compact graph: merge lines point to target lines\nrather than merge commits."),
        )
        .arg(
            Arg::new("style")
                .short('s')
                .long("style")
                .value_name("style")
                .help("Output style. One of [normal/thin|round|bold|double|ascii].\n  (First character can be used as abbreviation, e.g. '-s r')"),
        )
        .subcommand(
            Command::new("model")
                .about("Prints or permanently sets the branching model for a repository.")
                .color(ColorChoice::Never)
                .arg(
                    Arg::new("model")
                        .help("The branching model to be used. Available presets are [simple|git-flow|none].\nWhen not given, prints the currently set model."),
                )
                .arg(
                    Arg::new("list")
                        .short('l')
                        .long("list")
                        .action(ArgAction::SetTrue)
                        .help("List all available branching models."),
                ),
        )
}

#[derive(Serialize)]
struct RepoSettingsOut {
    model: String,
}

fn open_repo(path: &str, skip_owner_validation: bool) -> Result<git2::Repository, BoxError> {
    if skip_owner_validation {
        unsafe {
            let _ = git2::opts::set_verify_owner_validation(false);
        }
    }
    git2::Repository::discover(path).map_err(|e| -> BoxError {
        format!(
            "ERROR: {}\n       Navigate into a repository before running git-graph, or use option --path",
            e.message()
        )
        .into()
    })
}

fn read_repo_settings(path: &Path) -> Result<RepoSettings, BoxError> {
    let content = fs::read_to_string(path)?;
    let settings: RepoSettings = toml::from_str(&content)?;
    Ok(settings)
}

fn terminal_width_stdout() -> Option<usize> {
    if !std::io::stdout().is_terminal() {
        return None;
    }
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

fn run() -> Result<(), BoxError> {
    let models_dir = get_models_dir()?;
    let matches = build_cli().get_matches();

    let path = matches
        .get_one::<String>("path")
        .map(|s| s.as_str())
        .unwrap_or(".");
    let skip_owner = matches.get_flag("skip-repo-owner-validation");

    if let Some(model_matches) = matches.subcommand_matches("model") {
        if model_matches.get_flag("list") {
            for model in available_models(&models_dir)? {
                println!("{model}");
            }
            return Ok(());
        }
        let repo = open_repo(path, skip_owner)?;
        let settings_path = repo.path().join("git-graph.toml");
        if let Some(model_name) = model_matches.get_one::<String>("model") {
            let models = available_models(&models_dir)?;
            if !models.iter().any(|m| m == model_name) {
