    let no_color = matches.get_flag("no-color");
    let color_mode = if no_color {
        ColorMode::Never
    } else if let Some(v) = matches.get_one::<String>("color") {
        parse_color_mode(v)?
    } else {
        ColorMode::Auto
    };
    let use_color = match color_mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => std::io::stdout().is_terminal(),
    };

    let wrap_values: Option<Vec<&String>> = matches
        .get_many::<String>("wrap")
        .map(|v| v.collect::<Vec<_>>());
    let wrap = parse_wrap(wrap_values)?;
    let format = parse_format(matches.get_one::<String>("format"));
    let debug = matches.get_flag("debug");
    let svg = matches.get_flag("svg");

    let start = Instant::now();
    let graph = GitGraph::new(
        &repo,
        &branch_settings,
        matches.get_flag("local"),
        max_count,
    )?;
    if debug {
        for b in &graph.branches {
            let middle = if b.kind == BranchKind::Merge {
                " m "
            } else {
                "  "
            };
            eprintln!(
                "{} (col {}) ({:?}){}s: {:?}, t: {:?}",
                b.name, b.column, b.range, middle, b.source_group, b.target_group
            );
        }
    }
    let graph_time = start.elapsed();

    let print_start = Instant::now();
    let output = if svg {
        print::print_svg(&graph, debug)
    } else {
        let eff_width = effective_wrap_width(&wrap, graph.num_columns, terminal_width_stdout());
        print::print_text(
            &graph,
            &format,
            &wrap,
            eff_width,
            style,
            matches.get_flag("sparse"),
            matches.get_flag("reverse"),
            use_color,
        )
    };
    print!("{output}");
    let print_time = print_start.elapsed();
    if debug {
        eprintln!(
            "Graph construction: {:.1} ms, printing: {:.1} ms ({} commits)",
            graph_time.as_secs_f64() * 1000.0,
            print_time.as_secs_f64() * 1000.0,
            graph.commits.len()
        );
    }
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("{e}");
        process::exit(1);
    }
}
