import pathlib
p=pathlib.Path('src/format.rs'); t=p.read_text()
# Hyphen split rule
old="""        for sc in &tok.core {
            cur.push(*sc);
            if sc.ch == '-' {
                frags.push(std::mem::take(&mut cur));
            }
        }"""
new="""        for (ci, sc) in tok.core.iter().enumerate() {
            cur.push(*sc);
            if sc.ch == '-'
                && ci > 0
                && tok
                    .core
                    .get(ci + 1)
                    .map(|n| n.ch.is_alphanumeric())
                    .unwrap_or(false)
            {
                frags.push(std::mem::take(&mut cur));
            }
        }"""
assert old in t; t=t.replace(old,new)
# Space-only paragraph: return an indent-only line if first-line indent > 0
old="""    let has_core = tokens.iter().any(|t| !t.core.is_empty());
    if !has_core {
        return Vec::new();
    }"""
new="""    let has_core = tokens.iter().any(|t| !t.core.is_empty());
    if !has_core {
        let ind = if first_overall { indent1 } else { indent2 };
        if ind > 0 {
            return vec![indent_chars(ind)];
        }
        return Vec::new();
    }"""
assert old in t; t=t.replace(old,new)
# Blank internal paragraph indent rule
old="""        if para.is_empty() {
            let ind = if first_overall { indent1 } else { indent2 };
            out.push(indent_chars(ind));
            first_overall = false;
            continue;
        }"""
new="""        if para.is_empty() {
            // An empty paragraph inside a hard-wrapped line only carries
            // the subsequent indent when an initial indent is in use.
            let ind = if first_overall {
                indent1
            } else if indent1 > 0 {
                indent2
            } else {
                0
            };
            out.push(indent_chars(ind));
            first_overall = false;
            continue;
        }"""
assert old in t; t=t.replace(old,new)
p.write_text(t)
