                // before the placeholder is kept.
                if let Some(pos) = toks.iter().rposition(|t| matches!(t, Tok::Break)) {
                    toks.truncate(pos);
                    while matches!(toks.last(), Some(Tok::Break)) {
                        toks.pop();
                    }
                }
            }"""
assert old in t; t=t.replace(old,new); p.write_text(t)
