                    });
                    if per_commit_lines.get(i).map(|l| l.len()).unwrap_or(0) <= 1 {
                        needs_inserted[i] = true;
                    }
                } else {
                    placed.push(PlacedEvent {
                        event: HEvent::Merge { secondary: si },
                        commit: i,
                        after_dot: false,
                    });
                }
            }
        }"""
new="""        if let Some(&si) = secondary_by_source.get(&i) {
            let e = &secondaries[si];
            if e.target.is_some() && e.target_col != e.source_col {
                // If another branch already occupies the target column at
                // this row, the merge line cannot be drawn yet; it is
                // delayed until just before the target commit.
                let target_idx = e.target.unwrap();
                let occupied = graph.branches.iter().enumerate().any(|(bi, b)| {
                    bi != e.target_branch
                        && b.column == e.target_col
                        && b.range.0.map(|s| s <= i).unwrap_or(false)
                        && i <= b.range.1.unwrap_or(n)
                });
                if occupied && target_idx > 0 {
                    let pi = target_idx - 1;
                    let lo = e.source_col.min(e.target_col);
                    let hi = e.source_col.max(e.target_col);
                    let dot_col = col_of(graph, pi);
                    let after_dot = dot_col >= lo && dot_col <= hi;
                    if after_dot && per_commit_lines.get(pi).map(|l| l.len()).unwrap_or(0) <= 1 {
                        needs_inserted[pi] = true;
                    }
                    // Record delay on the edge (via a separate set below is
                    // awkward due to borrowing; use a marker list).
                    delayed_secondaries.push(si);
                    placed.push(PlacedEvent {
                        event: HEvent::Merge { secondary: si },
                        commit: pi,
                        after_dot,
                    });
                } else if sparse {
                    placed.push(PlacedEvent {
                        event: HEvent::Merge { secondary: si },
                        commit: i,
                        after_dot: true,
                    });
                    if per_commit_lines.get(i).map(|l| l.len()).unwrap_or(0) <= 1 {
                        needs_inserted[i] = true;
                    }
                } else {
                    placed.push(PlacedEvent {
                        event: HEvent::Merge { secondary: si },
                        commit: i,
                        after_dot: false,
                    });
                }
            }
        }"""
