# after placement loop (before Build slots), set delayed flags
t=t.replace("    // Build slots.\n", "    for si in delayed_secondaries {\n        secondaries[si].delayed = true;\n    }\n\n    // Build slots.\n")
# segment start for secondary: use event slot if sparse or delayed
old="""        let start = if sparse {
            match e.event_slot {
                Some(s) => s,
                None => dot_slot[&e.source],
            }
        } else {
