        };"""
new="""        let start = if sparse || e.delayed {
            match e.event_slot {
                Some(s) => s,
                None => dot_slot[&e.source],
            }
        } else {
            dot_slot[&e.source]
        };"""
assert old in t; t=t.replace(old,new)
p.write_text(t)
