            .collect();
    }
    let mut out_lines: Vec<String> = Vec::with_capacity(sublines.len());
    let mut active: Option<(u8, u32)> = None;
    for (idx, sub) in sublines.iter().enumerate() {
        let mut out = String::new();
        for sc in sub {
            if sc.indent {
                out.push(' ');
                continue;
            }
            let key = sc.color.map(|c| (c, sc.span));
            if key != active {
                if active.is_some() {
                    out.push_str("\\x1b[0m");
                }
                if let Some((c, _)) = key {
                    out.push_str(&format!("\\x1b[38;5;{c}m"));
                }
                active = key;
            }
            out.push(sc.ch);
